"use strict";(globalThis.webpackChunkncds_admin_docs=globalThis.webpackChunkncds_admin_docs||[]).push([[26864],{8892(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"release-note-step-guide-2.0.3","metadata":{"permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.3","source":"@site/blog-step-guide/v2.0.3.md","title":"v2.0.3","description":"step-guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v2.0.3)","date":"2026-07-14T00:00:00.000Z","tags":[{"inline":false,"label":"Step Guide","permalink":"/design-system/ncds-admin/releases/step-guide/tags/step-guide","description":"Step Guide tag description"},{"inline":false,"label":"Bugfix","permalink":"/design-system/ncds-admin/releases/step-guide/tags/bugfix","description":"Bug fix tag description"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"release-note-step-guide-2.0.3","title":"v2.0.3","date":"2026-07-14","tags":["step-guide","bugfix"]},"unlisted":false,"nextItem":{"title":"v2.0.2","permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.2"}},"content":"## step-guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v2.0.3)\\n\\n### \uae30\ub2a5 \uac1c\uc120\\n\\n- fix(step-guide): \ud234\ud301 \uc81c\ubaa9\xb7\ubcf4\uc870 \ud14d\uc2a4\ud2b8 \ud45c\uc2dc \uc624\ub958 \uc218\uc815\\n  - \uc81c\ubaa9: display:flex\xb7nowrap \uc81c\uac70\ud558\uace0 word-break \uc801\uc6a9\ud574 \uae34 \uc81c\ubaa9\uc774 \uc798\ub9ac\uc9c0 \uc54a\uace0 \uc904\ubc14\uafc8\ub418\ub3c4\ub85d \uc218\uc815\\n  - \ubcf4\uc870 \ud14d\uc2a4\ud2b8: line-clamp\ub97c padding \uc5c6\ub294 \ub0b4\ubd80 \uc694\uc18c\ub85c \ubd84\ub9ac\ud574 2\uc904 \ucd08\uacfc \uc2dc \ub2e4\uc74c \uc904\uc774 \ub178\ucd9c\ub418\ub358 \ubb38\uc81c \uc218\uc815"},{"id":"release-note-step-guide-2.0.2","metadata":{"permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.2","source":"@site/blog-step-guide/v2.0.2.md","title":"v2.0.2","description":"step-guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v2.0.2)","date":"2026-07-10T00:00:00.000Z","tags":[{"inline":false,"label":"Step Guide","permalink":"/design-system/ncds-admin/releases/step-guide/tags/step-guide","description":"Step Guide tag description"},{"inline":false,"label":"Bugfix","permalink":"/design-system/ncds-admin/releases/step-guide/tags/bugfix","description":"Bug fix tag description"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"release-note-step-guide-2.0.2","title":"v2.0.2","date":"2026-07-10","tags":["step-guide","bugfix"]},"unlisted":false,"prevItem":{"title":"v2.0.3","permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.3"},"nextItem":{"title":"v2.0.1","permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.1"}},"content":"## step-guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v2.0.2)\\n\\n### \uae30\ub2a5 \uac1c\uc120\\n\\n- \ud83d\udc1b fix(step-guide): \ud234\ud301 \ud14d\uc2a4\ud2b8 2\uc904 \ub9d0\uc904\uc784 \ucc98\ub9ac \uc81c\uac70"},{"id":"release-note-step-guide-2.0.1","metadata":{"permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.1","source":"@site/blog-step-guide/v2.0.1.md","title":"v2.0.1","description":"Step Guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v2.0.1)","date":"2026-07-09T00:00:00.000Z","tags":[{"inline":false,"label":"Step Guide","permalink":"/design-system/ncds-admin/releases/step-guide/tags/step-guide","description":"Step Guide tag description"},{"inline":false,"label":"Feature","permalink":"/design-system/ncds-admin/releases/step-guide/tags/feature","description":"New feature tag description"},{"inline":false,"label":"Improvement","permalink":"/design-system/ncds-admin/releases/step-guide/tags/improvement","description":"Improvement tag description"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"release-note-step-guide-2.0.1","title":"v2.0.1","date":"2026-07-09","tags":["step-guide","feature","improvement"]},"unlisted":false,"prevItem":{"title":"v2.0.2","permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.2"},"nextItem":{"title":"v2.0.0","permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.0"}},"content":"## Step Guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v2.0.1)\\n\\n\ub2e8\uacc4 \uc9c4\uc785 \uc81c\uc5b4\uc640 \ud654\uba74 \ubc16 \ubc30\uce58 \ucc98\ub9ac\ub97c \ubcf4\uac15\ud55c **\ud328\uce58 \ub9b4\ub9ac\uc988**\uc785\ub2c8\ub2e4. v2.0 \ub77c\uc778\uc758 \uc5f0\uc7a5\uc774\ubbc0\ub85c CDN \uacbd\ub85c\ub294 \uae30\uc874 `@ncds/step-guide/2.0/` \uadf8\ub300\ub85c\uc774\uba70, \uc0ac\uc6a9\ucc98\ub294 **\ubcc4\ub3c4 URL \ubcc0\uacbd \uc5c6\uc774** \ucd5c\uc2e0 \ub3d9\uc791\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e0\uaddc \uae30\ub2a5\\n\\n- **`onBeforeChange` \ucf5c\ubc31** \u2014 \uac01 \ub2e8\uacc4\ub85c \ub118\uc5b4\uac00\uae30 \uc9c1\uc804\uc5d0 \uc2e4\ud589\ud560 \ud568\uc218\ub97c \uc9c0\uc815\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac15\uc870\ud560 \uc694\uc18c\ub97c \ubbf8\ub9ac \uc2a4\ud06c\ub864\ud558\uac70\ub098 \uc900\ube44\ud558\ub294 \ub4f1 \uc9c4\uc785 \uc804 \ucc98\ub9ac\uc5d0 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.\\n- **`zIndex` \uc8fc\uc785 \uc635\uc158** \u2014 \ucf54\uce58\ub9c8\ud06c\uc758 z-index \ub97c \uc635\uc158\uc73c\ub85c \uc9c1\uc811 \uc9c0\uc815\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. (\ub2e4\ub978 \uc694\uc18c\uc5d0 \uac00\ub824\uc9c0\ub294 \uacbd\uc6b0 \uc870\uc815)\\n- **\ub098\uc911\uc5d0 \ub098\ud0c0\ub098\ub294 \uc694\uc18c \uac15\uc870** \u2014 \uac01 \ub2e8\uacc4\ub97c \ud45c\uc2dc\ud558\ub294 \uc2dc\uc810\ub9c8\ub2e4 \uc140\ub809\ud130\ub97c \ub2e4\uc2dc \uc870\ud68c\ud569\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc5c6\ub2e4\uac00 \ub4a4\ub2a6\uac8c \ub80c\ub354\ub418\ub294 \uc694\uc18c\ub3c4 \uac15\uc870\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \uac1c\uc120\\n\\n- **\ubdf0\ud3ec\ud2b8 clamp \xb7 4\ubc29\ud5a5 \uc7ac\ubc30\uce58** \u2014 \ud0c0\uac9f\uc774\ub098 \uce74\ub4dc\uac00 \ud654\uba74 \ubc16\uc73c\ub85c \ub098\uac08 \ub54c, \uc2a4\ud06c\ub864 \uc774\ud6c4\uc758 \uc2e4\uc81c \uc704\uce58\ub97c \uae30\uc900\uc73c\ub85c \ubc30\uce58\ub97c \ub2e4\uc2dc \uacb0\uc815\ud569\ub2c8\ub2e4.\\n  - \ud654\uba74\uc744 \uaf49 \ucc44\uc6cc \uc5b4\ub514\uc5d0\ub3c4 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\ub294 \ud0c0\uac9f\uc740 \uce74\ub4dc\ub97c \ud0c0\uac9f \uc548\ucabd \uc88c\uc0c1\ub2e8\uc5d0 \ubc30\uce58\ud569\ub2c8\ub2e4.\\n  - clamp \ub85c \uce74\ub4dc\uac00 \ubc00\ub824 \ud654\uc0b4\ud45c\uac00 \ud0c0\uac9f\uc744 \ubc97\uc5b4\ub098\uba74 \ud654\uc0b4\ud45c\ub97c \uc228\uae41\ub2c8\ub2e4.\\n- `maxScrollTop` \uc744 `clientHeight` \uae30\uc900\uc73c\ub85c \uacc4\uc0b0\ud558\ub3c4\ub85d \uc815\uc815\ud588\uc2b5\ub2c8\ub2e4.\\n\\n### \ubb38\uc11c\\n\\n- **[Viewport Clamp](/docs/step-guide/viewport-clamp)** \u2014 \uc2a4\ud06c\ub864 \uae30\uc900 \ubc30\uce58\xb7\ud0c0\uac9f \uc548\ucabd \ubc30\uce58\xb7\ud654\uc0b4\ud45c \uc228\uae40 \ub3d9\uc791 \uc124\uba85\\n- **[z-index](/docs/step-guide/z-index)** \u2014 `zIndex` \uc635\uc158\uacfc stacking context \ud55c\uacc4\\n- **[onBeforeChange](/docs/step-guide/on-before-change)** \u2014 \ub2e8\uacc4 \uc9c4\uc785 \uc804 \ucf5c\ubc31 \uc0ac\uc6a9\ubc95\xb7\uc608\uc2dc\\n- **[Options](/docs/step-guide/options)** \u2014 `onBeforeChange`, `zIndex` \ubc18\uc601"},{"id":"release-note-step-guide-2.0.0","metadata":{"permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.0","source":"@site/blog-step-guide/v2.0.0.md","title":"v2.0.0","description":"Step Guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v2.0.0)","date":"2026-05-15T00:00:00.000Z","tags":[{"inline":false,"label":"Step Guide","permalink":"/design-system/ncds-admin/releases/step-guide/tags/step-guide","description":"Step Guide tag description"},{"inline":false,"label":"Feature","permalink":"/design-system/ncds-admin/releases/step-guide/tags/feature","description":"New feature tag description"},{"inline":false,"label":"Improvement","permalink":"/design-system/ncds-admin/releases/step-guide/tags/improvement","description":"Improvement tag description"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"release-note-step-guide-2.0.0","title":"v2.0.0","date":"2026-05-15T00:00:00.000Z","tags":["step-guide","feature","improvement"]},"unlisted":false,"prevItem":{"title":"v2.0.1","permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.1"},"nextItem":{"title":"v1.0.0","permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-1.0.0"}},"content":"## Step Guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v2.0.0)\\n\\nDES-SPEC-057 Coachmark \uc0ac\uc591\uc5d0 \ub9de\ucdb0 NCUA \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \uae30\ubc18\uc73c\ub85c \uc804\uba74 \ub9ac\ub274\uc5bc\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n\\n### Breaking changes\\n\\n- **CSS \ud074\ub798\uc2a4 prefix**: `commerce-ui-*` \u2192 `ncua-coachmark-*`\\n- **NCUA CSS \uc758\uc874\uc131 \ucd94\uac00**: NCUA `main.min.css` \uac00 \ud398\uc774\uc9c0\uc5d0 \uba3c\uc800 \ub85c\ub4dc\ub418\uc5b4 \uc788\uc5b4\uc57c \uc2dc\uac01\uc774 \uc815\uc0c1 \ud45c\uc2dc\ub429\ub2c8\ub2e4.\\n- **`description`, `subText` \uac00 \ucd5c\ub300 2\uc904\ub85c \ud074\ub7a8\ud504**\ub429\ub2c8\ub2e4 (v1 \uc740 \uc904 \uc218 \uc81c\ud55c \uc5c6\uc74c, \ucd08\uacfc \uc2dc \ub9d0\uc904\uc784)\\n- **\ubc84\ud2bc\xb7\uce74\uc6b4\ud130\uc758 \uc2dc\uac01**\uc774 ui-admin \ub124\uc774\ud2f0\ube0c \ud074\ub798\uc2a4(`ncua-btn`, `ncua-carousel-number-group`)\ub85c \ubcc0\uacbd\\n- **CDN \uacbd\ub85c**\uac00 `@ncds/step-guide/2.0/` \uc73c\ub85c \ubd84\ub9ac\ub429\ub2c8\ub2e4. v1 \uc0ac\uc6a9\ucc98\ub294 `@ncds/step-guide/1.0/` \uadf8\ub300\ub85c \ub3d9\uc791.\\n- **`Step.element` \ud0c0\uc785**: `string | null` (CSS \uc120\ud0dd\uc790). HTMLElement \uc9c1\uc811 \uc804\ub2ec\uc740 \uc9c0\uc6d0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e0\uaddc \uae30\ub2a5\\n\\n- **`Step.subText`** \uc2ac\ub86f \u2014 \ubcf8\ubb38 \uc544\ub798\uc5d0 \ud68c\uc0c9 \ubc15\uc2a4 \ud615\ud0dc\uc758 \ubcf4\uc870 \uc548\ub0b4 \ud14d\uc2a4\ud2b8\\n- **\uc704\uce58 4\ubc29\ud5a5 \uc9c0\uc6d0** \u2014 `position` \uc635\uc158\uc5d0 `top`, `left` \ucd94\uac00\\n- **\uc790\ub3d9 flip** \u2014 \ud234\ud301\uc774 \ud654\uba74 \ubc16\uc73c\ub85c \ub098\uac00\uba74 \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc804\ud658. \uc591\ucabd \ubaa8\ub450 overflow \uba74 \ub354 \uc5ec\uc720 \uc788\ub294 \ucabd \uc120\ud0dd\\n- **\\"STEP N\\" prefix \uc790\ub3d9 \ub178\ucd9c** \u2014 \ucd1d step \uc774 2\uac1c \uc774\uc0c1\uc774\uba74 \ud0c0\uc774\ud2c0 \uc55e\uc5d0 \uc790\ub3d9 \ucd94\uac00\\n- **\uae30\ubcf8 \ubc84\ud2bc \ub77c\ubca8 \ud55c\uad6d\uc5b4\ud654** \u2014 `Prev/Next/Done/Skip` \u2192 `\uc774\uc804/\ub2e4\uc74c/\uc644\ub8cc/\ub098\uc911\uc5d0 \ud558\uae30`\\n\\n### \uac1c\uc120\\n\\n- \uac00\ub3c5\uc131\xb7\uc720\uc9c0\ubcf4\uc218\uc131 \ub9ac\ud329\ud1a0\ub9c1 (\uba54\uc11c\ub4dc \ubd84\ud560, \ud5ec\ud37c \ucd94\ucd9c)\\n- Vitest + jsdom \uae30\ubc18 \ud14c\uc2a4\ud2b8 14\uac74 \ucd94\uac00\\n\\n### \ubb38\uc11c\\n\\n- **[Quick Start](/docs/step-guide/quick-start)** \u2014 NCUA CSS \uc0ac\uc804 \uc694\uad6c\uc0ac\ud56d\xb7v2 CDN URL \uac31\uc2e0\\n- **[Options](/docs/step-guide/options)** \u2014 `subText`, 4\ubc29\ud5a5 position \ubc18\uc601\\n- **[Position](/docs/step-guide/position)** \u2014 4\ubc29\ud5a5 + \uc790\ub3d9 flip \ub3d9\uc791 \uc124\uba85"},{"id":"release-note-step-guide-1.0.0","metadata":{"permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-1.0.0","source":"@site/blog-step-guide/v1.0.0.md","title":"v1.0.0","description":"Step Guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v1.0.0)","date":"2024-01-28T00:00:00.000Z","tags":[{"inline":false,"label":"Step Guide","permalink":"/design-system/ncds-admin/releases/step-guide/tags/step-guide","description":"Step Guide tag description"},{"inline":false,"label":"Feature","permalink":"/design-system/ncds-admin/releases/step-guide/tags/feature","description":"New feature tag description"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"release-note-step-guide-1.0.0","title":"v1.0.0","date":"2024-01-28T00:00:00.000Z","tags":["step-guide","feature"]},"unlisted":false,"prevItem":{"title":"v2.0.0","permalink":"/design-system/ncds-admin/releases/step-guide/release-note-step-guide-2.0.0"}},"content":"## Step Guide \ub9b4\ub9ac\uc988 \ub178\ud2b8 (v1.0.0)\\n\\n### \uc2e0\uaddc \uae30\ub2a5\\n\\n- **[\uc2a4\ud15d \uac00\uc774\ub4dc](/docs/step-guide/quick-start)** \uae30\ubcf8 \uae30\ub2a5\uc744 \ucd94\uac00\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n- \uc0ac\uc6a9\uc790 \uac00\uc774\ub4dc\ub97c \uc704\ud55c \uc2a4\ud15d\ubcc4 \ud29c\ud1a0\ub9ac\uc5bc \uae30\ub2a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.\\n\\n### \ubb38\uc11c\\n\\n- Step Guide\uc758 **[\ud035 \uc2a4\ud0c0\ud2b8](/docs/step-guide/quick-start)** \ubb38\uc11c\ub97c \ucd94\uac00\ud558\uc600\uc2b5\ub2c8\ub2e4.\\n- Step Guide\uc758 **[\uc635\uc158 \uc124\uc815](/docs/step-guide/options)** \ubb38\uc11c\ub97c \ucd94\uac00\ud558\uc600\uc2b5\ub2c8\ub2e4."}]}}')}}]);